INSERT INTO public.news_posts (slug, title, category, excerpt, body, author, published) VALUES
('kajiado-water-project-launch','Kajiado Town water project brings taps closer to 4,000 homes','County News','A new borehole and distribution line commissioned this week is expected to cut daily water queues in three estates.','Residents of Kajiado Town will spend less time queueing for water after the county commissioned a new borehole and distribution line serving three estates.\n\nSpeaking at the launch, county officials said the project adds capacity for roughly 4,000 households and will be run with a community water committee that reports monthly on meter readings and revenue.\n\nBus Radio 99.9FM listeners raised water rationing as their top concern in our morning phone-ins for three consecutive weeks. The station will keep following the project and publish the committee''s first report on air.','Bus Radio Newsroom',true),
('youth-newsroom-training','Twenty young reporters trained in the Bus Radio community newsroom','Youth','A two-week practical course covered interviewing, phone recording, fact-checking and safety for community correspondents.','Twenty young people from Kajiado Central and Kajiado East completed a two-week community reporting course hosted at the Bus Radio 99.9FM studio.\n\nThe course covered interviewing, recording clean audio on a phone, verifying claims before broadcast, and staying safe while reporting on sensitive local issues.\n\nGraduates will feed weekly ward updates into the county bulletin, and the best submissions will air on Habari za Kaunti. Listeners can send tips and recordings through the Report page on this website.','Bus Radio Newsroom',true),
('maa-language-preservation','Maa language programming expands to weekend afternoons','Culture','Elders and young speakers share proverbs, oral history and music in an expanded Maa-language slot.','Bus Radio 99.9FM is expanding Maa-language programming to weekend afternoons following steady listener demand.\n\nThe slot pairs elders with young speakers to discuss proverbs, oral history, naming traditions and pastoralist knowledge, mixed with Maa music from across the county.\n\nSchools in Kajiado Town have asked for recordings to use in class, and the station is preparing a short archive of the best segments.','Bus Radio Newsroom',true),
('county-health-outreach','Free health outreach reaches Kajiado wards after on-air campaign','Health','Screening for blood pressure, diabetes and maternal health ran across five wards for a week.','A week-long free health outreach covering blood pressure, diabetes screening and maternal health services ran across five Kajiado wards.\n\nHealth workers said turnout was strongest where the schedule was announced on radio the previous evening, with several hundred people screened each day.\n\nBus Radio 99.9FM carried daily announcements and hosted a live question session with clinical officers who answered listener calls on medication and follow-up visits.','Bus Radio Newsroom',true),
('ward-accountability-forum','Ward accountability forum broadcast live from Kajiado Town','Governance','Residents put development questions directly to ward representatives in an open, on-air forum.','Residents put questions on roads, bursaries and water projects directly to their ward representatives during an open forum broadcast live on Bus Radio 99.9FM.\n\nThe two-hour session mixed floor questions with calls and messages from listeners across the county, with the station keeping a public list of the commitments made.\n\nFollow-up editions will check progress on each commitment. Send your ward''s issues through the Report page and they will be raised in the next forum.','Bus Radio Newsroom',true),
('livestock-market-prices','Livestock market prices steady as rains improve pasture','Community','Traders at Kajiado''s main market report firmer prices as pasture recovers after good rains.','Traders at Kajiado''s main livestock market report steadier prices as pasture recovers following good rains across the county.\n\nBuyers from Nairobi returned in larger numbers, and market officials say volumes are close to the levels seen before the last dry spell.\n\nBus Radio 99.9FM carries market updates in the midday bulletin so pastoralists can plan sales before travelling.','Bus Radio Newsroom',true)
